   "format": "{{ kv(null) }}",
   "allowFailure": true
  },
  {
   "id": "int_key",
   "type": "io.kestra.plugin.core.debug.Return",
   "format": "{{ kv(1) }}",
   "allowFailure": true
  },
  {
   "id": "key_expr",
   "type": "io.kestra.plugin.core.debug.Return",
   "format": "{{ kv('k' ~ '') }}",
   "allowFailure": true
  },
  {
   "id": "too_many_args",
