   "format": "{{ kv('k', 'w9c.fn', false, 1) }}",
   "allowFailure": true
  },
  {
   "id": "unknown_named",
   "type": "io.kestra.plugin.core.debug.Return",
   "format": "{{ kv(key='k', foo=1) }}",
   "allowFailure": true
  }
 ]
}

