 {"dot_existing", "{\"a\":{\"b\":1,\"c\":2}}", "[{\"key\":\"a.b\",\"value\":9}]"},
 {"dot_missing_level", "{\"a\":1}", "[{\"key\":\"x.y.z\",\"value\":1}]"},
 {"dot_through_scalar", "{\"a\":1}", "[{\"key\":\"a.b\",\"value\":2}]"},
 {"dot_two", "{\"a\":{\"b\":1}}", "[{\"key\":\"a.c\",\"value\":2},{\"key\":\"d\",\"value\":{\"e\":1}}]"},
 {"dot_prefix_conflict", "{\"a\":1}", "[{\"key\":\"a\",\"value\":{\"z\":1}},{\"key\":\"a.b\",\"value\":2}]"},
 {"single_value", "{\"a\":1}", "[{\"value\":[1,2]}]"},
 {"single_value_null", "{\"a\":1}", "[{\"value\":null}]"},
 {"dot_on_scalar_existing", "5", "[{\"key\":\"a\",\"value\":1}]"},
 {"null_in_map", "{\"a\":1,\"b\":2}", "{\"a\":null}"},
 {"list_plain", "{\"a\":1}", "[1,2]"},
 {"mixed_entries", "{\"a\":1}", "[{\"key\":\"a\",\"value\":1},{\"value\":2}]"},
 {"unkeyed_then_keyed", "{\"a\":1}", "[{\"value\":2},{\"key\":\"a\",\"value\":1}]"},
 {"blank_key", "{\"a\":1}", "[{\"key\":\" \",\"value\":1}]"},
 {"nonstring_key", "{\"a\":1}", "[{\"key\":1,\"value\":1}]"},
 {"extra_field", "{\"a\":1}", "[{\"key\":\"a\",\"value\":1,\"other\":1}]"},
 {"two_unkeyed", "{\"a\":1}", "[{\"value\":1},{\"value\":2}]"},
 {"dot_key_in_map", "{\"a\":1}", "{\"x.y\":1}"},
 {"map_over_map_with_list_of_maps", "{\"a\":[{\"b\":1}]}", "{\"a\":[{\"c\":2}]}"},
 {"empty_list", "{\"a\":1}", "[]"},
 {"empty_map", "{\"a\":1}", "{}"},
 {"missing_map", null, "{\"a\":1}"},
 {"missing_entries", null, "[{\"key\":\"a.b\",\"value\":1}]"},
 {"missing_single", null, "[{\"value\":3}]"},
 {"missing_scalar", null, "7"},
 {"dot_deep_merge_existing", "{\"a\":{\"b\":{\"c\":1}}}", "[{\"key\":\"a.b.d\",\"value\":2}]"},
